    // Check output pointers for NULL; if any is NULL, return error without writing
    if ((momentum == NULL) || (momentum_norm == NULL) || 
        (energy_axis == NULL) || (energy == NULL)) {
        return ADCS_E_NULL;
    }

    // Otherwise, zero all outputs first
    *momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    *momentum_norm = 0.0;
    *energy_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
    *energy = 0.0;

    // Check if wheels pointer is NULL
    if (wheels == NULL) {
        return ADCS_E_NULL;
    }

    // Check if count is within valid range [1, 16]
    if ((count < 1) || (count > 16)) {
        return ADCS_E_RANGE;
    }

    double total_energy = 0.0;
    adcs_vec3_t acc_energy_axis = {0.0, 0.0, 0.0};
    adcs_vec3_t normalized_axis;

    // Validate each wheel and accumulate energy and energy_axis contributions
    for (size_t i = 0; i < count; ++i) {
        // Validate inertia: must be finite and positive
        if ((!isfinite(wheels[i].inertia_kg_m2)) || (wheels[i].inertia_kg_m2 <= 0.0)) {
            return ADCS_E_RANGE;
        }

        // Validate speed: must be finite
        if (!isfinite(wheels[i].speed_rad_s)) {
            return ADCS_E_RANGE;
        }

        // Normalize the axis vector; fails if non-finite or norm <= ADCS_EPS_NORM
        if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &normalized_axis) != ADCS_OK) {
            return ADCS_E_RANGE;
        }

        // Calculate kinetic energy for this wheel: e_i = 0.5 * inertia * speed^2
        double e_i = 0.5 * wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s * wheels[i].speed_rad_s;

        // Accumulate total stored energy
        total_energy += e_i;

        // Accumulate energy_axis: sum of e_i * normalize(axis_i)
        acc_energy_axis = adcs_vec3_add(&acc_energy_axis, &adcs_vec3_scale(&normalized_axis, e_i));
    }

    // Assign computed energy and energy_axis to outputs
    *energy = total_energy;
    *energy_axis = acc_energy_axis;

    // Compute linked-library cluster momentum
    adcs_status_t status = adcs_wheel_momentum(wheels, count, momentum);
    if (status != ADCS_OK) {
        return status;
    }

    // Compute momentum norm
    *momentum_norm = adcs_vec3_norm(momentum);

    return ADCS_OK;
}

