        *energy_axis = (adcs_vec3_t){0, 0, 0};
        *energy = 0.0;
        return ADCS_E_RANGE;
    }

    // Initialize accumulators
    *energy = 0.0;
    *energy_axis = (adcs_vec3_t){0.0, 0.0, 0.0};

    adcs_vec3_t norm_axis;
    size_t i;

    // Validate each wheel and accumulate energy/energy_axis
    for (i = 0; i < count; i++) {
        double inertia = wheels[i].inertia_kg_m2;
        double speed = wheels[i].speed_rad_s;

        // Check finiteness of scalar values
        if ((!isfinite(inertia)) || (!isfinite(speed))) {
            *momentum = (adcs_vec3_t){0, 0, 0};
            *momentum_norm = 0.0;
            *energy_axis = (adcs_vec3_t){0, 0, 0};
            *energy = 0.0;
            return ADCS_E_RANGE;
        }

        // Check positive inertia
        if (inertia <= 0.0) {
            *momentum = (adcs_vec3_t){0, 0, 0};
            *momentum_norm = 0.0;
            *energy_axis = (adcs_vec3_t){0, 0, 0};
            *energy = 0.0;
            return ADCS_E_RANGE;
        }

        // Check finiteness of axis vector
        if (!adcs_is_finite_vec3(&wheels[i].axis_body)) {
            *momentum = (adcs_vec3_t){0, 0, 0};
            *momentum_norm = 0.0;
            *energy_axis = (adcs_vec3_t){0, 0, 0};
            *energy = 0.0;
            return ADCS_E_RANGE;
        }

        // Normalize axis
        if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &norm_axis) != ADCS_OK) {
            // This implies norm <= ADCS_EPS_NORM or other degenerate case
            *momentum = (adcs_vec3_t){0, 0, 0};
            *momentum_norm = 0.0;
            *energy_axis = (adcs_vec3_t){0, 0, 0};
            *energy = 0.0;
            return ADCS_E_RANGE;
        }

        // Calculate kinetic energy: e_i = 0.5 * inertia * speed^2
        double e_i = 0.5 * inertia * speed * speed;

        // Accumulate total energy
        *energy += e_i;

        // Accumulate energy_axis: sum(e_i * normalize(axis_i))
        adcs_vec3_t term = adcs_vec3_scale(&norm_axis, e_i);
        *energy_axis = adcs_vec3_add(energy_axis, &term);
    }

    // Compute cluster momentum using linked library function
    adcs_status_t status = adcs_wheel_momentum(wheels, count, momentum);
    if (status != ADCS_OK) {
        // Failure handling: zero all outputs
        *momentum = (adcs_vec3_t){0, 0, 0};
        *momentum_norm = 0.0;
        *energy_axis = (adcs_vec3_t){0, 0, 0};
        *energy = 0.0;
        return status;
    }

    // Compute momentum norm
    *momentum_norm = adcs_vec3_norm(momentum);

    return ADCS_OK;
}

